const rnd = (id) => { let h = 7; for (const c of String(id)) h = (h * 31 + c.charCodeAt(0)) % 100003; return h; };
export const TEXTS = T.map((x) => { const r = rnd(x.id); return { ...x, at: new Date(x.at).getTime(), likes: 8 + (r % 460), liked: false, views: 20 + (r % 900), uses: 3 + (r % 150) }; });

